-- Gmail Archive Sync schema. There is deliberately no table of successfully
-- copied messages: only failures are stored per message (FULL_SPECS.md §6.1).
-- UUIDs are generated by the application (UUIDv7) for index locality.
-- Columns named enc_* hold crypto.Ring ciphertexts ("keyid.base64").

CREATE TABLE app_settings (
    id                       boolean PRIMARY KEY DEFAULT true CHECK (id), -- single row
    oauth_client_id          text NOT NULL DEFAULT '',
    enc_oauth_client_secret  text NOT NULL DEFAULT '',
    session_retention_days   integer NOT NULL DEFAULT 365 CHECK (session_retention_days > 0),
    event_retention_days     integer NOT NULL DEFAULT 90 CHECK (event_retention_days > 0),
    enc_notification_webhook text NOT NULL DEFAULT '',
    created_at               timestamptz NOT NULL DEFAULT now(),
    updated_at               timestamptz NOT NULL DEFAULT now()
);
INSERT INTO app_settings (id) VALUES (true);

CREATE TABLE destinations (
    id            uuid PRIMARY KEY,
    name          text NOT NULL UNIQUE,
    host          text NOT NULL,
    port          integer NOT NULL CHECK (port BETWEEN 1 AND 65535),
    tls_mode      text NOT NULL DEFAULT 'implicit' CHECK (tls_mode IN ('implicit', 'starttls', 'none')),
    tls_skip_verify boolean NOT NULL DEFAULT false,
    username      text NOT NULL,
    enc_password  text NOT NULL,
    hierarchy_delimiter text NOT NULL DEFAULT '',
    enabled       boolean NOT NULL DEFAULT true,
    created_at    timestamptz NOT NULL DEFAULT now(),
    updated_at    timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE accounts (
    id                     uuid PRIMARY KEY,
    name                   text NOT NULL UNIQUE,
    gmail_address          text NOT NULL DEFAULT '',
    enc_refresh_token      text NOT NULL DEFAULT '',
    authorised_at          timestamptz, -- when the refresh token was issued (diagnoses 7-day Testing expiry)
    status                 text NOT NULL DEFAULT 'unauthorised'
                           CHECK (status IN ('unauthorised', 'ok', 'needs_reauth', 'disabled', 'error')),
    last_connection_check  timestamptz,
    last_connection_error  text NOT NULL DEFAULT '',
    destination_id         uuid REFERENCES destinations (id) ON DELETE RESTRICT,
    created_at             timestamptz NOT NULL DEFAULT now(),
    updated_at             timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE account_sync_settings (
    account_id           uuid PRIMARY KEY REFERENCES accounts (id) ON DELETE CASCADE,
    enabled              boolean NOT NULL DEFAULT false,
    schedule_interval_seconds integer NOT NULL DEFAULT 7200 CHECK (schedule_interval_seconds >= 300),
    initial_sync_after   date,
    archive_folder       text NOT NULL DEFAULT 'Archive',
    sent_folder          text NOT NULL DEFAULT 'Sent',
    inbox_folder         text NOT NULL DEFAULT 'INBOX',
    -- Matchers: [{"kind":"id|name|prefix","value":"...","case_insensitive":false}]
    excluded_labels      jsonb NOT NULL DEFAULT '[{"kind":"id","value":"SPAM"},{"kind":"id","value":"TRASH"},{"kind":"id","value":"DRAFT"}]',
    -- {"<label id>": "Folder/Name"}
    label_mapping        jsonb NOT NULL DEFAULT '{}',
    -- {"unread_as_seen": true, "starred_as_flagged": true, "folder_labels": []}
    flag_mapping         jsonb NOT NULL DEFAULT '{"unread_as_seen":true,"starred_as_flagged":true,"folder_labels":[]}',
    subscribe_folders    boolean NOT NULL DEFAULT true,
    worker_count         integer NOT NULL DEFAULT 4 CHECK (worker_count BETWEEN 1 AND 64),
    rate_fraction        real NOT NULL DEFAULT 0.3 CHECK (rate_fraction > 0 AND rate_fraction <= 1),
    batch_size           integer NOT NULL DEFAULT 100 CHECK (batch_size BETWEEN 1 AND 500),
    retry_max_attempts   integer NOT NULL DEFAULT 10 CHECK (retry_max_attempts >= 0),
    created_at           timestamptz NOT NULL DEFAULT now(),
    updated_at           timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE account_labels (
    account_id   uuid NOT NULL REFERENCES accounts (id) ON DELETE CASCADE,
    label_id     text NOT NULL,
    name         text NOT NULL,
    type         text NOT NULL CHECK (type IN ('system', 'user')),
    last_seen_at timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (account_id, label_id)
);

CREATE TABLE sync_state (
    account_id                uuid PRIMARY KEY REFERENCES accounts (id) ON DELETE CASCADE,
    last_successful_history_id bigint,
    last_successful_sync_at   timestamptz,
    start_history_id          bigint,
    start_history_at          timestamptz, -- when start_history_id was read
    history_checkpoint_at     timestamptz, -- when last_successful_history_id was read; the cutoff of a reconcile
    initial_sync_cursor       jsonb,
    initial_sync_completed    boolean NOT NULL DEFAULT false,
    learned_rate_fraction     real, -- share of the Gmail quota this account tolerated at the end of the last session
    updated_at                timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE sync_sessions (
    id                   uuid PRIMARY KEY,
    account_id           uuid NOT NULL REFERENCES accounts (id) ON DELETE CASCADE,
    status               text NOT NULL DEFAULT 'queued'
                         CHECK (status IN ('queued', 'running', 'completed', 'completed_with_errors',
                                           'failed', 'cancelled', 'abandoned')),
    trigger_type         text NOT NULL CHECK (trigger_type IN ('scheduled', 'manual', 'initial', 'retry', 'recovery')),
    sync_type            text NOT NULL CHECK (sync_type IN ('initial', 'incremental', 'reconcile', 'retry')),
    params               jsonb NOT NULL DEFAULT '{}', -- e.g. reconcile range, retry message ids
    phase                text NOT NULL DEFAULT '',
    current_folder       text NOT NULL DEFAULT '',
    started_at           timestamptz,
    finished_at          timestamptz,
    heartbeat_at         timestamptz,
    worker_id            text NOT NULL DEFAULT '',
    cancel_requested_at  timestamptz,
    starting_history_id  bigint,
    ending_history_id    bigint,
    discovered_count     bigint NOT NULL DEFAULT 0,
    processed_count      bigint NOT NULL DEFAULT 0,
    copied_count         bigint NOT NULL DEFAULT 0,
    skipped_count        bigint NOT NULL DEFAULT 0,
    failed_count         bigint NOT NULL DEFAULT 0,
    recovered_count      bigint NOT NULL DEFAULT 0,
    folders_created_count bigint NOT NULL DEFAULT 0,
    api_request_count    bigint NOT NULL DEFAULT 0,
    bytes_copied         bigint NOT NULL DEFAULT 0,
    duration_ms          bigint,
    last_error           text NOT NULL DEFAULT '',
    run_at               timestamptz NOT NULL DEFAULT now(), -- earliest start (queue ordering)
    lease_until          timestamptz,
    created_at           timestamptz NOT NULL DEFAULT now()
);
-- At most one queued/running session per account, enforced by the database.
CREATE UNIQUE INDEX sync_sessions_one_active_per_account
    ON sync_sessions (account_id) WHERE status IN ('queued', 'running');
CREATE INDEX sync_sessions_account_started ON sync_sessions (account_id, started_at DESC);
CREATE INDEX sync_sessions_status ON sync_sessions (status);
CREATE INDEX sync_sessions_created ON sync_sessions (created_at DESC);
CREATE INDEX sync_sessions_queue ON sync_sessions (run_at) WHERE status = 'queued';

CREATE TABLE sync_session_events (
    id          bigserial PRIMARY KEY,
    session_id  uuid NOT NULL REFERENCES sync_sessions (id) ON DELETE CASCADE,
    event_type  text NOT NULL,
    severity    text NOT NULL DEFAULT 'info' CHECK (severity IN ('debug', 'info', 'warning', 'error')),
    message     text NOT NULL,
    metadata    jsonb NOT NULL DEFAULT '{}',
    created_at  timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX sync_session_events_session ON sync_session_events (session_id, id);
CREATE INDEX sync_session_events_created ON sync_session_events (created_at);

CREATE TABLE failed_messages (
    id                uuid PRIMARY KEY,
    account_id        uuid NOT NULL REFERENCES accounts (id) ON DELETE CASCADE,
    gmail_message_id  text NOT NULL,
    gmail_thread_id   text NOT NULL DEFAULT '',
    subject           text NOT NULL DEFAULT '',
    sender            text NOT NULL DEFAULT '',
    recipients        jsonb NOT NULL DEFAULT '[]',
    message_date      timestamptz,
    intended_folders  jsonb NOT NULL DEFAULT '[]',
    completed_folders jsonb NOT NULL DEFAULT '[]',
    failed_folders    jsonb NOT NULL DEFAULT '[]',
    error_category    text NOT NULL,
    error_message     text NOT NULL DEFAULT '',
    error_history     jsonb NOT NULL DEFAULT '[]', -- last 10 attempts
    status            text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'retrying', 'ignored')),
    retry_exhausted   boolean NOT NULL DEFAULT false,
    retry_requested   boolean NOT NULL DEFAULT false, -- a person asked for a retry: even permanent categories are tried once
    attempt_count     integer NOT NULL DEFAULT 1,
    next_retry_at     timestamptz,
    first_failed_at   timestamptz NOT NULL DEFAULT now(),
    last_failed_at    timestamptz NOT NULL DEFAULT now(),
    last_attempted_at timestamptz NOT NULL DEFAULT now(),
    last_session_id   uuid REFERENCES sync_sessions (id) ON DELETE SET NULL,
    created_at        timestamptz NOT NULL DEFAULT now(),
    updated_at        timestamptz NOT NULL DEFAULT now(),
    UNIQUE (account_id, gmail_message_id)
);
CREATE INDEX failed_messages_retry ON failed_messages (status, next_retry_at);
CREATE INDEX failed_messages_account_failed ON failed_messages (account_id, last_failed_at DESC);
